import sys


def main():
    lines = sys.stdin.read().split("\n")
    n, q = map(int, lines[0].split())
    shelves = list(map(int, lines[1].split()))
    for k in range(q):
        t, x, y = map(int, lines[2 + k].split())
        if t == 1:
            shelves[x - 1] = y
        else:
            total = 0
            for idx in range(x - 1, y):
                total += shelves[idx]
            print(total)


